package site.kael.conversationcompiler.controller.settings;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import site.kael.conversationcompiler.domain.settings.*; import site.kael.conversationcompiler.service.settings.ModelProviderService; import java.util.*;
@RestController @RequestMapping("/api/v1/model-providers") public class ModelProviderController { private final ModelProviderService service; public ModelProviderController(ModelProviderService s){service=s;} @GetMapping public List<ModelProvider> list(){return service.list();} @GetMapping("/{id}") public ModelProvider get(@PathVariable String id){return service.get(id);} @PostMapping("/fetch-models") public Map<String,Object> fetch(@RequestBody FetchModelsRequest r){return Map.of("models",service.fetch(r),"fetchedAt",java.time.Instant.now().toString());} @PostMapping public ResponseEntity<ModelProvider> create(@RequestBody ModelProviderRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @PutMapping("/{id}") public ModelProvider update(@PathVariable String id,@RequestBody ModelProviderRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable String id){service.delete(id);} }
